def fizzbuzz(n: int) -> list[str]:
    """Devuelve una lista de strings del 1 al n con la regla FizzBuzz."""
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s: str) -> int:
    """Convierte una cadena de duración (ej: '1h30m', '45m', '2h') a minutos totales."""
    total_minutos = 0
    for char in s:
        if char == 'h':
            total_minutos += int(s[:s.index(char)]) * 60
        elif char == 'm':
            total_minutos += int(s[:s.index(char)])
    return total_minutos

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def contar_palabras(texto: str) -> dict[str, int]:
    """Devuelve un diccionario con la frecuencia de cada palabra en el texto."""
    import re
    texto = texto.lower()
    palabras = re.findall(r'[a-z0-9]+', texto)
    return dict(zip(palabras, [palabras.count(palabra) for palabra in palabras]))

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos."""
    if not 1 <= n <= 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    valores = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    resultado = []
    for valor, simbolo in valores:
        while n >= valor:
            resultado.append(simbolo)
            n -= valor
    return ''.join(resultado)

def desde_romano(s: str) -> int:
    """Convierte una cadena de números romanos a su equivalente entero."""
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s)):
        if i + 1 < len(s) and valores[s[i]] < valores[s[i + 1]]:
            total -= valores[s[i]]
        else:
            total += valores[s[i]]
    return total

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = lista[0]
    max_longitud = 1
    current_elemento = lista[0]
    current_longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == current_elemento:
            current_longitud += 1
        else:
            if current_longitud > max_longitud:
                max_longitud = current_longitud
                max_elemento = current_elemento
            current_elemento = lista[i]
            current_longitud = 1

    if current_longitud > max_longitud:
        max_longitud = current_longitud
        max_elemento = current_elemento

    return (max_elemento, max_longitud)

def a_camel(s: str) -> str:
    """Convierte texto en snake_case a camelCase."""
    return ''.join(word.capitalize() for word in s.split('_'))

def a_snake(s: str) -> str:
    """Convierte camelCase o PascalCase a snake_case."""
    return ''.join(['_' + c.lower() if c.isupper() else c for c in s]).lstrip('_').lower()

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = False
    is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a: int, b: int) -> int:
    """Calcula el máximo común divisor de dos enteros no negativos."""
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Fusiona intervalos que se tocan en un extremo."""
    if not intervalos:
        return []
    intervalos.sort()
    resultado = [intervalos[0]]
    for inicio, fin in intervalos[1:]:
        if inicio <= resultado[-1][1]:
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], fin))
        else:
            resultado.append((inicio, fin))
    return resultado

def es_anagrama(a: str, b: str) -> bool:
