    return sorted(a.lower().replace(" ", "")) == sorted(b.lower().replace(" ", ""))

def comprimir(s: str) -> str:
    if not s:
        return s

    resultado = []
    i = 0
    while i < len(s):
        caracter = s[i]
        contador = 1
        while i + contador < len(s) and s[i + contador] == caracter:
            contador += 1

        codificado = caracter + str(contador)
        if len(codificado) < len(caracter) + 1:
            resultado.append(codificado)
        else:
            resultado.append(caracter)

        i += contador

    comprimido = ''.join(resultado)
    return comprimido if len(comprimido) < len(s) else s

def balanceado(s: str) -> bool:
    """Devuelve True si los paréntesis, corchetes y llaves están balanceados y anidados correctamente."""
    pila = []
    pares = {')': '(', ']': '[', '}': '{'}
    for char in s:
        if char in '([{':
            pila.append(char)
        elif char in ')]}':
            if not pila or pila[-1] != pares[char]:
                return False
            pila.pop()
    return not pila

