def raiz_digital(n: int) -> int:
    """Calcula la raíz digital de un número sumando sus dígitos recursivamente."""
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def sin_duplicados(lista):
    """Elimina elementos repetidos conservando el orden de primera aparición."""
    resultado = []
    visto = set()
    for elemento in lista:
        if elemento not in visto:
            resultado.append(elemento)
            visto.add(elemento)
    return resultado

def formatear_bytes(n: int) -> str:
    """Convierte bytes a texto legible usando base 1024."""
    if n < 1024:
        return f"{n} B"
    if n < 1024**2:
        return f"{n / 1024:.1f} KB"
    if n < 1024**3:
        return f"{n / (1024**2):.1f} MB"
    return f"{n / (1024**3):.1f} GB"

