def balanceado(s: str) -> bool:
    """
    Devuelve True si los paréntesis, corchetes y llaves del string están bien balanceados y anidados.
    Los demás caracteres se ignoran.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())

    for char in s:
        if char in openers:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return not stack

def mediana(nums):
    if not nums:
        return None
    nums = sorted(nums)
    n = len(nums)
    if n % 2 == 1:
        return nums[n // 2]
    else:
        return (nums[n // 2 - 1] + nums[n // 2]) / 2

