def dedup(lista):
    """Elimina duplicados conservando el orden de primera aparición."""
    seen = set()
    result = []
    for item in lista:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def anidar(plano: dict) -> dict:
    """Convierte un dict de claves con puntos en un dict anidado.

    Ej: {'a.b': 1} -> {'a': {'b': 1}}
    """
    resultado = {}
    for clave, valor in plano.items():
        partes = clave.split('.')
        nodo = resultado
        for parte in partes[:-1]:
            if parte not in nodo:
                nodo[parte] = {}
            nodo = nodo[parte]
        nodo[partes[-1]] = valor
    return resultado

def comprimir(s: str) -> str:
    if not s:
        return ""
    resultado = []
    contador = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            contador += 1
        else:
            resultado.append(s[i - 1] + str(contador))
