def promedio_movil(nums, ventana):
    if len(nums) < ventana:
        return []
    return [sum(nums[i:i+ventana]) / ventana for i in range(len(nums) - ventana + 1)]

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando múltiplos de 1024."""
    unidades = ["B", "KB", "MB", "GB"]
    if n < 1024:
        return f"{n} {unidades[0]}"
    for i in range(1, len(unidades)):
        n /= 1024
        if n < 1024:
            return f"{n:.1f} {unidades[i]}"
    return f"{n:.1f} {unidades[-1]}"

def parsear_query(s: str) -> dict:
    """Convierte una query string 'a=1&b=2' en un dict {'a':'1','b':'2'}."""
    if not s:
        return {}
    return dict(item.split("=", 1) for item in s.split("&"))

def contar_islas(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    filas, cols = len(grid), len(grid[0])
    visitados = [[False] * cols for _ in range(filas)]

    def dfs(r: int, c: int) -> None:
        visitados[r][c] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < filas and 0 <= nc < cols and not visitados[nr][nc] and grid[nr][nc] == 1:
                dfs(nr, nc)

    islas = 0
    for i in range(filas):
        for j in range(cols):
            if grid[i][j] == 1 and not visitados[i][j]:
                dfs(i, j)
                islas += 1

    return islas

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],     # borrado
                    dp[i][j - 1],     # inserción
                    dp[i - 1][j - 1]  # sustitución
                )

    return dp[m][n]

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not any(c.isupper() for c in p):
        return False
    if not any(c.islower() for c in p):
        return False
    if not any(c.isdigit() for c in p):
        return False
    if not any(not c.isalnum() for c in p):
        return False
    return True

def a_base(n: int, base: int) -> str:
    """Convierte un entero no negativo a su representación en la base dada (2-16)."""
    if n == 0:
        return "0"
    digits = "0123456789abcdef"
    result = []
    while n > 0:
        result.append(digits[n % base])
        n //= base
    return "".join(reversed(result))

def interseccion(a: list[int], b: list[int]) -> list[int]:
    """Devuelve la intersección ordenada sin repetidos de dos listas ordenadas."""
    resultado = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if not resultado or resultado[-1] != a[i]:
                resultado.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return resultado

from datetime import datetime

def dias_entre(a: str, b: str) -> int:
    """Calcula la cantidad de días entre dos fechas en formato 'YYYY-MM-DD'."""
    return abs((datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days)

def campo_csv(s: str) -> str:
    """Prepara un campo para CSV: si contiene coma, comilla doble o salto de linea,
    lo devuelve entre comillas dobles y con las comillas internas duplicadas."""
    if ',' in s or '"' in s or '\n' in s:
        return '"' + s.replace('"', '""') + '"'
    return s

def titular(s: str) -> str:
    """Pone en mayúscula la primera letra de cada palabra, excepto 'de', 'del', 'la', 'las', 'el', 'los' e 'y' cuando no son la primera palabra."""
    palabras = s.split()
    resultado = []
    for i, palabra in enumerate(palabras):
        if i == 0:
            resultado.append(palabra.capitalize())
        else:
            if palabra.lower() in ('de', 'del', 'la', 'las', 'el', 'los', 'y'):
                resultado.append(palabra.lower())
            else:
                resultado.append(palabra.capitalize())
    return ' '.join(resultado)

def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            resultado.append(elemento)
    return resultado

def sumar_romanos(a: str, b: str) -> str:
    """Suma dos números romanos y devuelve el resultado en romano."""
    simbolos = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    inverso = {v: k for k, v in simbolos.items()}

    def romano_a_entero(s: str) -> int:
        total = 0
        prev = 0
        for char in reversed(s):
            valor = simbolos[char]
            if valor < prev:
                total -= valor
            else:
                total += valor
            prev = valor
        return total

    def entero_a_romano(n: int) -> str:
        valores = [
            (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
            (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
            (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
        ]
        resultado = []
        for valor, simbolo in valores:
            while n >= valor:
                resultado.append(simbolo)
                n -= valor
        return ''.join(resultado)

    entero_a = romano_a_entero(a)
    entero_b = romano_a_entero(b)
    resultado = entero_a + entero_b
    return entero_a_romano(resultado)

def obtener(d, camino, defecto=None):
    partes = camino.split('.')
    valor = d
    for parte in partes:
        if isinstance(valor, dict) and parte in valor:
            valor = valor[parte]
        else:
            return defecto
    return valor

def con_reintentos(fn, veces):
    for i in range(veces):
        try:
            return fn()
        except Exception:
            if i == veces - 1:
                raise
